#nullable enable // autogenerated

using MVZ2.Vanilla.Properties;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Level;
using PVZEngine.Modifiers;

namespace MVZ2.GameContent.Buffs.SeedPacks
{
    [AutoBuffDefinition(VanillaBuffNames.SeedPack.bunbunmaruNewspaper)]
    public class BunbunmaruNewspaperBuff : BuffDefinition
    {
        public BunbunmaruNewspaperBuff(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new FloatModifier(EngineSeedProps.COST, NumberOperator.Set, PROP_COST));
        }
        public static float GetCost(Buff buff) => buff.GetProperty<float>(PROP_COST);
        public static void SetCost(Buff buff, float value) => buff.SetProperty(PROP_COST, value);
        public static readonly VanillaBuffPropertyMeta<float> PROP_COST = new VanillaBuffPropertyMeta<float>("cost");
    }
}
